pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> (i32) {
    assert!(N >= 0, "N must be non-negative");
    let n = N as usize;

    assert!(
        a.len() == n && b.len() == n,
        "a and b must have length exactly N"
    );

    let mut sum: i64 = 0;

    for i in 0..n {
        let idx_i32 = i as i32;
        let bi = b[i];

        // Per problem statement, bi is either idx_i32 or idx_i32 + 1.
        // We treat anything not equal to idx_i32 as the idx_i32 + 1 case.
        let val: i32 = if bi == idx_i32 { 1 } else { 2 };

        a[i] = val;
        sum += val as i64;
    }

    // Ensure the returned i32 is representable (important for large N).
    assert!(
        sum >= i32::MIN as i64 && sum <= i32::MAX as i64,
        "sum does not fit in i32"
    );

    sum as i32
}